import Image from "next/image";

// Brand SVGs generated by scripts/build-brand-svgs.mjs (public/icons, public/campaign, public/jelly).
// All are decorative next to visible text → empty alt. SVGs are served as-is (no optimiser needed).

export type IconName =
  | "staff-augmentation"
  | "dedicated-teams"
  | "specialists"
  | "leadership"
  | "frontend"
  | "backend"
  | "cloud-devops"
  | "ai-data"
  | "quality"
  | "ecommerce";

export function BrandIcon({ name, size = 28, className = "" }: { name: IconName; size?: number; className?: string }) {
  return <Image src={`/icons/${name}.svg`} width={size} height={size} alt="" aria-hidden="true" unoptimized className={className} />;
}

export type CampaignName = "jelly-drop" | "tech-bench-inbox" | "jelly-box";

// Supplied raster artwork overrides the generated SVG (optimised to AVIF/WebP by next/image).
// Source originals live in assets/generated/.
const RASTER: Partial<Record<CampaignName, string>> = {
  "jelly-drop": "/campaign/jelly-drop.jpg",
  "tech-bench-inbox": "/campaign/tech-bench-inbox.jpg",
};

export function CampaignArt({ name, className = "", priority = false }: { name: CampaignName; className?: string; priority?: boolean }) {
  const raster = RASTER[name];
  return (
    <Image
      src={raster ?? `/campaign/${name}.svg`}
      width={1200}
      height={1200}
      sizes="(min-width: 1024px) 448px, 100vw"
      alt=""
      aria-hidden="true"
      unoptimized={!raster}
      priority={priority}
      className={`h-auto w-full rounded-[var(--radius-card)] ${className}`}
    />
  );
}

export type JellyEnergy = "electric" | "acid" | "heat";
export type JellyShape = "bubble" | "capsule" | "soft-square" | "loop" | "ring" | "bean" | "double-bubble" | "wave" | "crescent" | "disc" | "drop" | "tri-node";

/** Floating jelly accent (motion via .jelly-accent in globals.css; still under reduced motion). */
export function JellyAccent({ energy, shape, className = "", priority = false }: { energy: JellyEnergy; shape: JellyShape; className?: string; priority?: boolean }) {
  // `priority` for above-the-fold accents: they can be the LCP element on small screens.
  return <Image src={`/jelly/${energy}-${shape}.svg`} width={512} height={512} alt="" aria-hidden="true" unoptimized priority={priority} className={`jelly-accent pointer-events-none select-none ${className}`} />;
}
